CREATE TABLE public.author_profiles (user_id uuid PRIMARY KEY, display_name text NOT NULL, bio text NOT NULL DEFAULT '', domain text NOT NULL DEFAULT '', photo_path text, contact_email text, published boolean NOT NULL DEFAULT false);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.author_profiles TO authenticated; GRANT ALL ON public.author_profiles TO service_role;
ALTER TABLE public.author_profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY author_read ON public.author_profiles FOR SELECT TO authenticated USING (published OR user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY author_write ON public.author_profiles FOR ALL TO authenticated USING (user_id=auth.uid() OR public.has_role(auth.uid(),'admin')) WITH CHECK (user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.courses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL DEFAULT auth.uid(), title text NOT NULL, description text NOT NULL DEFAULT '', domain text NOT NULL DEFAULT '', price numeric NOT NULL DEFAULT 0 CHECK(price>=0), currency text NOT NULL DEFAULT 'USD' CHECK(currency IN ('USD','CDF','XAF','XOF','EUR')), status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','published','refused')), cover_path text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.courses TO authenticated; GRANT ALL ON public.courses TO service_role;
ALTER TABLE public.courses ENABLE ROW LEVEL SECURITY;
CREATE POLICY course_read ON public.courses FOR SELECT TO authenticated USING(status='published' OR user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY course_submit ON public.courses FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND status='pending');
CREATE POLICY course_edit ON public.courses FOR UPDATE TO authenticated USING(user_id=auth.uid() AND status='pending') WITH CHECK(user_id=auth.uid() AND status='pending');
CREATE POLICY course_admin ON public.courses FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.course_enrollments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL DEFAULT auth.uid(), course_id uuid NOT NULL REFERENCES public.courses(id), status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','active','refused')), amount numeric NOT NULL DEFAULT 0, currency text NOT NULL DEFAULT 'USD', payment_method text, payment_reference text, progress integer NOT NULL DEFAULT 0 CHECK(progress BETWEEN 0 AND 100), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,course_id));
GRANT SELECT,INSERT,UPDATE ON public.course_enrollments TO authenticated; GRANT ALL ON public.course_enrollments TO service_role;
ALTER TABLE public.course_enrollments ENABLE ROW LEVEL SECURITY;
CREATE POLICY enrollment_read ON public.course_enrollments FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY enrollment_insert ON public.course_enrollments FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid());
CREATE POLICY enrollment_update ON public.course_enrollments FOR UPDATE TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin')) WITH CHECK(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.validate_enrollment() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE c public.courses; BEGIN SELECT * INTO c FROM public.courses WHERE id=NEW.course_id; IF TG_OP='INSERT' THEN IF c.id IS NULL OR c.status!='published' OR NEW.user_id IS DISTINCT FROM auth.uid() OR NEW.amount IS DISTINCT FROM c.price OR NEW.currency IS DISTINCT FROM c.currency THEN RAISE EXCEPTION 'Inscription invalide'; END IF; NEW.status:=CASE WHEN c.price=0 THEN 'active' ELSE 'pending' END; NEW.progress:=0; IF c.price>0 AND length(trim(COALESCE(NEW.payment_reference,'')))=0 THEN RAISE EXCEPTION 'Référence de paiement requise'; END IF; ELSE IF NEW.user_id IS DISTINCT FROM OLD.user_id OR NEW.course_id IS DISTINCT FROM OLD.course_id OR NEW.amount IS DISTINCT FROM OLD.amount OR NEW.currency IS DISTINCT FROM OLD.currency THEN RAISE EXCEPTION 'Inscription non réaffectable'; END IF; IF NOT public.has_role(auth.uid(),'admin') AND (NEW.status IS DISTINCT FROM OLD.status OR NEW.payment_reference IS DISTINCT FROM OLD.payment_reference OR OLD.status!='active') THEN RAISE EXCEPTION 'Modification interdite'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER validate_enrollment BEFORE INSERT OR UPDATE ON public.course_enrollments FOR EACH ROW EXECUTE FUNCTION public.validate_enrollment();
CREATE FUNCTION public.can_access_course(cid uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND EXISTS(SELECT 1 FROM public.courses c WHERE c.id=cid AND (c.user_id=auth.uid() OR public.has_role(auth.uid(),'admin') OR (c.status='published' AND EXISTS(SELECT 1 FROM public.course_enrollments e WHERE e.course_id=c.id AND e.user_id=auth.uid() AND e.status='active' AND e.amount=c.price AND e.currency=c.currency)))) $$;
CREATE TABLE public.course_resources (course_id uuid PRIMARY KEY REFERENCES public.courses(id), file_path text NOT NULL);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.course_resources TO authenticated; GRANT ALL ON public.course_resources TO service_role;
ALTER TABLE public.course_resources ENABLE ROW LEVEL SECURITY;
CREATE POLICY resource_read ON public.course_resources FOR SELECT TO authenticated USING(public.can_access_course(course_id));
CREATE POLICY resource_write ON public.course_resources FOR ALL TO authenticated USING(EXISTS(SELECT 1 FROM public.courses c WHERE c.id=course_id AND (c.user_id=auth.uid() OR public.has_role(auth.uid(),'admin')))) WITH CHECK(EXISTS(SELECT 1 FROM public.courses c WHERE c.id=course_id AND (c.user_id=auth.uid() OR public.has_role(auth.uid(),'admin'))));
CREATE TABLE public.admin_knowledge (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), title text NOT NULL, content text NOT NULL DEFAULT '', file_path text, enabled boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.admin_knowledge TO authenticated; GRANT ALL ON public.admin_knowledge TO service_role;
ALTER TABLE public.admin_knowledge ENABLE ROW LEVEL SECURITY;
CREATE POLICY knowledge_admin ON public.admin_knowledge FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.user_messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), sender_id uuid NOT NULL DEFAULT auth.uid(), recipient_id uuid NOT NULL, content text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.user_messages TO authenticated; GRANT ALL ON public.user_messages TO service_role;
ALTER TABLE public.user_messages ENABLE ROW LEVEL SECURITY;
CREATE POLICY message_read ON public.user_messages FOR SELECT TO authenticated USING(recipient_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY message_send ON public.user_messages FOR INSERT TO authenticated WITH CHECK(sender_id=auth.uid() AND public.has_role(auth.uid(),'admin'));
CREATE TABLE public.exchange_rates (currency text PRIMARY KEY CHECK(currency IN ('USD','CDF','XAF','XOF','EUR')), units_per_usd numeric NOT NULL CHECK(units_per_usd>0), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.exchange_rates TO authenticated; GRANT ALL ON public.exchange_rates TO service_role;
ALTER TABLE public.exchange_rates ENABLE ROW LEVEL SECURITY;
CREATE POLICY rate_read ON public.exchange_rates FOR SELECT TO authenticated USING(true);
CREATE POLICY rate_admin ON public.exchange_rates FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
ALTER TABLE public.orders ADD COLUMN currency text NOT NULL DEFAULT 'USD', ADD COLUMN payment_currency text, ADD COLUMN payment_amount numeric;
ALTER TABLE public.subscriptions ADD COLUMN payment_currency text, ADD COLUMN payment_amount numeric;
ALTER TABLE public.opportunities ADD COLUMN cover_path text;
CREATE POLICY community_upload ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='community' AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE POLICY community_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='community' AND ((storage.foldername(name))[1]=auth.uid()::text OR public.has_role(auth.uid(),'admin') OR EXISTS(SELECT 1 FROM public.course_resources r WHERE r.file_path=name AND public.can_access_course(r.course_id)) OR EXISTS(SELECT 1 FROM public.courses c WHERE c.cover_path=name AND c.status='published') OR EXISTS(SELECT 1 FROM public.author_profiles a WHERE a.photo_path=name AND a.published) OR EXISTS(SELECT 1 FROM public.opportunities o WHERE o.cover_path=name AND o.status='active')));
CREATE POLICY community_delete ON storage.objects FOR DELETE TO authenticated USING(bucket_id='community' AND ((storage.foldername(name))[1]=auth.uid()::text OR public.has_role(auth.uid(),'admin')));
CREATE POLICY profile_admin_update ON public.profiles FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE POLICY docs_admin ON public.user_docs FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.search_bersa_knowledge(query_text text) RETURNS TABLE(title text,content text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT k.title,left(k.content,6000) FROM public.admin_knowledge k WHERE auth.uid() IS NOT NULL AND k.enabled AND length(trim(query_text))>0 AND to_tsvector('simple',k.title||' '||k.content) @@ plainto_tsquery('simple',query_text) ORDER BY ts_rank(to_tsvector('simple',k.title||' '||k.content),plainto_tsquery('simple',query_text)) DESC LIMIT 3 $$;
REVOKE ALL ON FUNCTION public.search_bersa_knowledge(text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.search_bersa_knowledge(text) TO authenticated;
CREATE FUNCTION public.bersa_admin_stats() RETURNS json LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Accès réservé'; END IF; RETURN json_build_object('users',(SELECT count(*) FROM auth.users),'signups',(SELECT COALESCE(json_agg(x),'[]'::json) FROM (SELECT date_trunc('day',created_at) AS day,count(*) AS count FROM auth.users GROUP BY 1 ORDER BY 1 DESC) x)); END $$;
REVOKE ALL ON FUNCTION public.bersa_admin_stats() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.bersa_admin_stats() TO authenticated;